DNS_TYPE_NAMES <- c(
    "1" = "A",
    "2" = "NS",
    "5" = "CNAME",
    "6" = "SOA",
    "12" = "PTR",
    "15" = "MX",
    "16" = "TXT",
    "28" = "AAAA"
)
RCODE_NAMES <- c("NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused")
type_name <- function(type) {
  name <- DNS_TYPE_NAMES[as.character(type)]
  if (is.na(name)) paste0("TYPE", type) else unname(name)
}
class_name <- function(class) if (class == 1) "IN" else paste0("CLASS", class)
rcode_name <- function(code) if (code < length(RCODE_NAMES)) RCODE_NAMES[[code + 1L]] else paste0(
    "RCODE",
    code
)
dns_chunk <- function(message, position, size) {
  if (position + size > length(message)) malformed("dns: truncated")
  byte_slice(message, position, size)
}
dns_byte <- function(message, position) dns_chunk(message, position, 1L)[[1L]]
dns_integer <- function(message, position, size) read_integer(dns_chunk(message, position, size), 0L, size)
dns_label <- function(label) {
  paste(vapply(label, function(byte) {
    if (byte >= 33L && byte <= 126L && !(byte %in% c(46L, 92L))) intToUtf8(byte) else sprintf("\\%03d", byte)
  }, ""), collapse = "")
}
dns_name <- function(message, position) {
  labels <- character()
  pointers <- 0L
  after <- NULL
  repeat {
    size <- dns_byte(message, position)
    if (size == 0L) {
      if (is.null(after)) after <- position + 1L
      break
    }
    if (size >= 192L) {
      low <- dns_byte(message, position + 1L)
      if (is.null(after)) after <- position + 2L
      pointers <- pointers + 1L
      if (pointers > 16L) malformed("dns: compression loop")
      target <- (size - 192L) * 256L + low
      if (target >= length(message)) malformed("dns: pointer out of range")
      position <- target
    } else if (size >= 64L) malformed("dns: bad label type") else {
      labels <- c(labels, dns_label(dns_chunk(message, position + 1L, size)))
      position <- position + size + 1L
    }
  }
  list(name = if (length(labels)) paste(labels, collapse = ".") else "<root>", after = after)
}
ipv6_notation <- function(address) {
  groups <- vapply(seq.int(0L, 14L, by = 2L), function(i) read_integer(address, i, 2L), 0)
  best_start <- 0L
  best_length <- 1L
  index <- 1L
  while (index <= length(groups)) {
    if (groups[[index]] != 0) {
      index <- index + 1L
      next
    }
    after <- index
    while (after <= length(groups) && groups[[after]] == 0) after <- after + 1L
    if (after - index > best_length) {
      best_start <- index
      best_length <- after - index
    }
    index <- after
  }
  texts <- sprintf("%x", as.integer(groups))
  if (!best_start) return(paste(texts, collapse = ":"))
  left <- if (best_start > 1L) texts[seq_len(best_start - 1L)] else character()
  after <- best_start + best_length
  right <- if (after <= length(groups)) texts[seq.int(after, length(groups))] else character()
  paste0(paste(left, collapse = ":"), "::", paste(right, collapse = ":"))
}
dns_rdata <- function(message, type, start, size) {
  if (type == 1) return(list(name = ipv4_notation(dns_integer(message, start, 4L)), after = start + 4L))
  if (type == 28) return(list(name = ipv6_notation(dns_chunk(message, start, 16L)), after = start + 16L))
  if (type %in% c(2, 5, 12)) return(dns_name(message, start))
  if (type == 15) {
    preference <- dns_integer(message, start, 2L)
    exchange <- dns_name(message, start + 2L)
    return(list(name = paste(preference, exchange$name), after = exchange$after))
  }
  if (type == 6) {
    primary <- dns_name(message, start)
    mailbox <- dns_name(message, primary$after)
    parts <- c(primary$name, mailbox$name)
    position <- mailbox$after
    for (i in seq_len(5L)) {
      parts <- c(parts, sprintf("%.0f", dns_integer(message, position, 4L)))
      position <- position + 4L
    }
    return(list(name = paste(parts, collapse = " "), after = position))
  }
  list(name = paste(size, "bytes"), after = start + size)
}
dns_record <- function(message, position, section, layer) {
  name <- dns_name(message, position)
  fixed <- dns_chunk(message, name$after, 10L)
  type <- read_integer(fixed, 0L, 2L)
  class <- read_integer(fixed, 2L, 2L)
  ttl <- read_integer(fixed, 4L, 4L)
  size <- read_integer(fixed, 8L, 2L)
  start <- name$after + 10L
  if (start + size > length(message)) malformed("dns: truncated")
  data <- dns_rdata(message, type, start, size)
  if (data$after != start + size) malformed("dns: bad rdata length")
  record <- paste(name$name, type_name(type), class_name(class), sprintf("%.0f", ttl), data$name)
  add_field(layer, section, record)
  if (section == "dns.answer" && type == 1) add_field(layer, "dns.a", read_integer(message, start, 4L))
  start + size
}
dissect_dns <- function(message) {
  header <- dns_chunk(message, 0L, 12L)
  flags <- read_integer(header, 2L, 2L)
  counts <- vapply(seq.int(4L, 10L, by = 2L), function(i) read_integer(header, i, 2L), 0)
  layer <- new_layer()
  set_field(layer, "dns.id", read_integer(header, 0L, 2L))
  set_field(layer, "dns.flags", flags)
  set_field(layer, "dns.flags.response", (flags %/% 32768) %% 2)
  set_field(layer, "dns.flags.opcode", (flags %/% 2048) %% 16)
  set_field(layer, "dns.flags.rcode", flags %% 16)
  names <- c("dns.count.queries", "dns.count.answers", "dns.count.auth_rr", "dns.count.add_rr")
  for (i in seq_along(names)) set_field(layer, names[[i]], counts[[i]])
  position <- 12L
  for (i in seq_len(counts[[1L]])) {
    name <- dns_name(message, position)
    tail <- dns_chunk(message, name$after, 4L)
    add_field(layer, "dns.qry.name", name$name)
    add_field(layer, "dns.qry.type", read_integer(tail, 0L, 2L))
    position <- name$after + 4L
  }
  sections <- c("dns.answer", "dns.authority", "dns.additional")
  for (i in seq_along(sections)) {
    for (j in seq_len(counts[[i + 1L]])) position <- dns_record(message, position, sections[[i]], layer)
  }
  layer
}

SEQUENCE_MODULUS <- 4294967296
MARKS <- c("retransmission", "out_of_order", "lost_segment", "duplicate_ack")
new_side <- function(name) {
  new_object(name = name, isn = NULL, mss = NULL, wscale = NULL, base = NULL,
             expected = NULL, advanced_at = NULL, intervals = character(), previous_ack = NULL,
             packets = 0L, payload = 0, marks = setNames(integer(length(MARKS)), MARKS))
}
endpoint_key <- function(endpoint) paste(sprintf("%.0f", endpoint), collapse = ":")
endpoint_pair <- function(first, second) {
  precedes <- first[[1L]] < second[[1L]] || (first[[1L]] == second[[1L]] && first[[2L]] <= second[[2L]])
  if (precedes) paste(endpoint_key(first), endpoint_key(second), sep = "/") else paste(
      endpoint_key(second),
      endpoint_key(first),
      sep = "/"
  )
}
new_tracker <- function() new_object(
    streams = list(),
    latest = new.env(hash = TRUE, parent = emptyenv()),
    duplicate_acks = list()
)
make_segment <- function(packet) {
  value <- function(name) packet_value(packet, name)
  list(packet = packet, number = packet$number, time = packet$time,
       source = c(value("ip.src"), value("tcp.srcport")), destination = c(
           value("ip.dst"),
           value("tcp.dstport")
       ),
       seq = value("tcp.seq_raw"), ack = value("tcp.ack_raw"), fin = value("tcp.flags.fin"),
       syn = value("tcp.flags.syn"), rst = value("tcp.flags.rst"), has_ack = value("tcp.flags.ack"),
       window = value("tcp.window"), length = value("tcp.len"))
}
syn_only <- function(segment) segment$syn == 1 && segment$has_ack == 0
syn_ack <- function(segment) segment$syn == 1 && segment$has_ack == 1
change_state <- function(stream, state, number) {
  stream$state <- state
  stream$history[[length(stream$history) + 1L]] <- list(state, number)
}
record_syn <- function(stream, side, segment) {
  side$isn <- segment$seq
  side$mss <- packet_value(segment$packet, "tcp.options.mss")
  side$wscale <- packet_value(segment$packet, "tcp.options.wscale")
  if (side$name == "client") stream$syn <- segment$number else stream$syn_ack <- segment$number
}
open_stream <- function(tracker, segment) {
  if (syn_ack(segment)) {
    client <- segment$destination
    server <- segment$source
    state <- "SYN_RECEIVED"
  } else {
    client <- segment$source
    server <- segment$destination
    state <- if (syn_only(segment)) "SYN_SENT" else "ESTABLISHED"
  }
  stream <- new_object(number = length(tracker$streams), client = client, server = server, state = state,
                       history = list(list(
                           state,
                           segment$number
                       )), start_time = segment$time, end_time = segment$time,
                       packets = 0L, bytes = 0, syn = NULL, syn_ack = NULL, handshake_ack = NULL,
                       events = list(), closer = "", final_ack = NULL, client_side = new_side("client"), server_side = new_side("server"))
  if (syn_ack(segment)) record_syn(stream, stream$server_side, segment) else if (syn_only(segment)) record_syn(
      stream,
      stream$client_side,
      segment
  )
  tracker$streams[[length(tracker$streams) + 1L]] <- stream
  stream
}
sequence_mark <- function(side, start, size, time) {
  if (is.null(side$expected) || start == side$expected) return(NULL)
  if (start > side$expected) return("lost_segment")
  if (paste(start, size, sep = ":") %in% side$intervals) return("retransmission")
  if (time - side$advanced_at < 3000) "out_of_order" else "retransmission"
}
analyze_segment <- function(tracker, stream, side, segment, start) {
  size <- segment$length + segment$syn + segment$fin
  mark <- NULL
  if (size >= 1) {
    mark <- sequence_mark(side, start, size, segment$time)
    side$intervals <- union(side$intervals, paste(start, size, sep = ":"))
    if (is.null(side$expected) || start + size > side$expected) {
      side$expected <- start + size
      side$advanced_at <- segment$time
    }
  } else if (segment$has_ack == 1 && segment$rst == 0) {
    previous <- side$previous_ack
    if (!is.null(previous) && segment$ack == previous$ack && segment$window == previous$window) {
      mark <- "duplicate_ack"
      previous$count <- previous$count + 1L
      tracker$duplicate_acks[[as.character(segment$number)]] <- c(previous$number, previous$count)
    }
  }
  if (segment$has_ack == 1 && !identical(mark, "duplicate_ack")) {
    side$previous_ack <- new_object(
        ack = segment$ack,
        window = segment$window,
        number = segment$number,
        count = 0L
    )
  }
  if (!is.null(mark)) {
    set_field(segment$packet, paste0("tcp.analysis.", mark), TRUE)
    side$marks[[mark]] <- side$marks[[mark]] + 1L
    stream$events[[length(stream$events) + 1L]] <- list(segment$number, side$name, mark, start, size)
  }
}
transition <- function(stream, side, segment) {
  state <- stream$state
  number <- segment$number
  if (segment$rst == 1) {
    if (!(state %in% c("CLOSED", "RESET"))) change_state(stream, "RESET", number)
  } else if (state == "SYN_SENT" && syn_ack(segment) && side$name == "server" && segment$ack == (stream$client_side$isn + 1) %% SEQUENCE_MODULUS) {
    change_state(stream, "SYN_RECEIVED", number)
    record_syn(stream, stream$server_side, segment)
  } else if (state == "SYN_RECEIVED" && side$name == "client" && segment$has_ack == 1 && segment$syn == 0 && segment$ack == (stream$server_side$isn + 1) %% SEQUENCE_MODULUS) {
    change_state(stream, "ESTABLISHED", number)
    stream$handshake_ack <- number
  } else if (state == "ESTABLISHED" && segment$fin == 1) {
    change_state(stream, "FIN_WAIT", number)
    stream$closer <- side$name
  } else if (state == "FIN_WAIT" && segment$fin == 1 && side$name != stream$closer) {
    change_state(stream, "CLOSING", number)
    stream$final_ack <- (segment$seq + segment$length + 1) %% SEQUENCE_MODULUS
  } else if (state == "CLOSING" && side$name == stream$closer && segment$has_ack == 1 && segment$ack == stream$final_ack) {
    change_state(stream, "CLOSED", number)
  }
}
track <- function(tracker, packet) {
  segment <- make_segment(packet)
  key <- endpoint_pair(segment$source, segment$destination)
  stream <- if (exists(key, envir = tracker$latest, inherits = FALSE)) tracker$latest[[key]] else NULL
  if (is.null(stream) || (stream$state %in% c("CLOSED", "RESET") && syn_only(segment))) {
    stream <- open_stream(tracker, segment)
    tracker$latest[[key]] <- stream
  }
  set_field(packet, "tcp.stream", stream$number)
  if (identical(segment$source, stream$client)) {
    side <- stream$client_side
    other <- stream$server_side
  } else {
    side <- stream$server_side
    other <- stream$client_side
  }
  if (is.null(side$base)) side$base <- segment$seq
  if (segment$has_ack == 1 && is.null(other$base)) other$base <- segment$ack
  relative <- (segment$seq - side$base) %% SEQUENCE_MODULUS
  set_field(packet, "tcp.seq", relative)
  if (segment$has_ack == 1) set_field(packet, "tcp.ack", (segment$ack - other$base) %% SEQUENCE_MODULUS)
  analyze_segment(tracker, stream, side, segment, relative)
  scaled <- !is.null(stream$client_side$wscale) && !is.null(stream$server_side$wscale)
  window <- if (scaled && segment$syn == 0) segment$window * (2 ^ side$wscale) else segment$window
  set_field(packet, "tcp.window.calc", window)
  transition(stream, side, segment)
  side$packets <- side$packets + 1L
  side$payload <- side$payload + segment$length
  stream$packets <- stream$packets + 1L
  stream$bytes <- stream$bytes + packet$length
  stream$end_time <- segment$time
}
flow_packets <- function(flow) flow$packets_a_to_b + flow$packets_b_to_a
flow_bytes <- function(flow) flow$bytes_a_to_b + flow$bytes_b_to_a
conversation_views <- function(packet) {
  source <- packet_value(packet, "ip.src")
  destination <- packet_value(packet, "ip.dst")
  views <- list(list(
      kind = "ipv4",
      key = endpoint_pair(c(source, -1), c(destination, -1)),
      source = c(source, -1),
      destination = c(destination, -1)
  ))
  if (field_exists(packet, "tcp.stream")) {
    views[[length(views) + 1L]] <- list(kind = "tcp", key = as.character(packet_value(packet, "tcp.stream")),
                                      source = c(source, packet_value(packet, "tcp.srcport")), destination = c(
                                          destination,
                                          packet_value(packet, "tcp.dstport")
                                      ))
  }
  if (field_exists(packet, "udp.srcport")) {
    first <- c(source, packet_value(packet, "udp.srcport"))
    second <- c(destination, packet_value(packet, "udp.dstport"))
    views[[length(views) + 1L]] <- list(
        kind = "udp",
        key = endpoint_pair(first, second),
        source = first,
        destination = second
    )
  }
  views
}
build_conversations <- function(packets) {
  table <- new.env(hash = TRUE, parent = emptyenv())
  flows <- list()
  for (packet in packets) {
    if (!field_exists(packet, "ip.src")) next
    for (view in conversation_views(packet)) {
      key <- paste(view$kind, view$key, sep = "|")
      if (!exists(key, envir = table, inherits = FALSE)) {
        flow <- new_object(kind = view$kind, endpoint_a = view$source, endpoint_b = view$destination,
                           first_number = packet$number, first_time = packet$time, last_time = packet$time,
                           packets_a_to_b = 0L, bytes_a_to_b = 0, packets_b_to_a = 0L, bytes_b_to_a = 0)
        table[[key]] <- flow
        flows[[length(flows) + 1L]] <- flow
      }
      flow <- table[[key]]
      if (identical(view$source, flow$endpoint_a)) {
        flow$packets_a_to_b <- flow$packets_a_to_b + 1L
        flow$bytes_a_to_b <- flow$bytes_a_to_b + packet$length
      } else {
        flow$packets_b_to_a <- flow$packets_b_to_a + 1L
        flow$bytes_b_to_a <- flow$bytes_b_to_a + packet$length
      }
      flow$last_time <- packet$time
    }
  }
  if (!length(flows)) return(flows)
  positions <- order(-vapply(flows, flow_bytes, 0), -vapply(flows, flow_packets, 0L),
                     match(vapply(flows, function(flow) flow$kind, ""), c("ipv4", "tcp", "udp")),
                     vapply(flows, function(flow) flow$first_number, 0), method = "radix")
  flows[positions]
}
endpoint_packets <- function(endpoint) endpoint$tx_packets + endpoint$rx_packets
endpoint_bytes <- function(endpoint) endpoint$tx_bytes + endpoint$rx_bytes
build_endpoints <- function(packets) {
  table <- new.env(hash = TRUE, parent = emptyenv())
  for (packet in packets) {
    if (!field_exists(packet, "ip.src")) next
    source <- packet_value(packet, "ip.src")
    destination <- packet_value(packet, "ip.dst")
    for (address in c(source, destination)) {
      key <- sprintf("%.0f", address)
      if (!exists(key, envir = table, inherits = FALSE)) {
        table[[key]] <- new_object(
            address = address,
            tx_packets = 0L,
            tx_bytes = 0,
            rx_packets = 0L,
            rx_bytes = 0
        )
      }
    }
    sender <- table[[sprintf("%.0f", source)]]
    receiver <- table[[sprintf("%.0f", destination)]]
    sender$tx_packets <- sender$tx_packets + 1L
    sender$tx_bytes <- sender$tx_bytes + packet$length
    receiver$rx_packets <- receiver$rx_packets + 1L
    receiver$rx_bytes <- receiver$rx_bytes + packet$length
  }
  endpoints <- as.list(table, all.names = TRUE)
  if (!length(endpoints)) return(endpoints)
  endpoints[order(-vapply(endpoints, endpoint_bytes, 0), -vapply(endpoints, endpoint_packets, 0L),
                  vapply(endpoints, function(endpoint) endpoint$address, 0), method = "radix")]
}

new_object <- function(...) list2env(list(...), parent = emptyenv())
new_packet <- function(number, time, size) {
  new_object(number = number, time = time, length = size, data = integer(),
             error = NULL, layers = character(), fields = list(), remaining = integer())
}
field_values <- function(object, name) {
  value <- object$fields[[name]]
  if (is.null(value)) list() else value
}
packet_value <- function(object, name) {
  values <- field_values(object, name)
  if (length(values)) values[[1L]] else NULL
}
field_exists <- function(object, name) !is.null(object$fields[[name]])
set_field <- function(object, name, value) object$fields[[name]] <- list(value)
add_field <- function(object, name, value) {
  object$fields[[name]] <- c(field_values(object, name), list(value))
}
read_capture <- function(path) {
  packets <- list()
  dumps <- list()
  lines <- readLines(path, warn = FALSE)
  for (number in seq_along(lines)) {
    line <- lines[[number]]
    if (startsWith(line, "PACKET ")) {
      header <- as.numeric(strsplit(line, " ", fixed = TRUE)[[1L]][2L:4L])
      packets[[length(packets) + 1L]] <- new_packet(header[[1L]], header[[2L]], header[[3L]])
      dumps[[length(packets)]] <- list()
    } else if (nzchar(line)) {
      index <- length(packets)
      dumps[[index]][[length(dumps[[index]]) + 1L]] <- list(number, line)
    }
  }
  for (index in seq_along(packets)) {
    packet <- packets[[index]]
    bytes <- integer()
    for (entry in dumps[[index]]) {
      number <- entry[[1L]]
      line <- entry[[2L]]
      if (!grepl("^[0-9a-f]{4}  [0-9a-f]{2}( [0-9a-f]{2}){0,15}$", line)) {
        packet$error <- paste("dump: bad line", number)
        break
      }
      if (strtoi(substr(line, 1L, 4L), base = 16L) != length(bytes)) {
        packet$error <- paste("dump: offset mismatch at line", number)
        break
      }
      bytes <- c(bytes, strtoi(strsplit(substring(line, 7L), " ", fixed = TRUE)[[1L]], base = 16L))
    }
    if (is.null(packet$error)) {
      if (length(bytes) != packet$length) {
        packet$error <- sprintf("dump: length mismatch (header %.0f, data %d)", packet$length, length(bytes))
      } else packet$data <- bytes
    }
  }
  packets
}
hex_dump_lines <- function(data) {
  lines <- character()
  if (!length(data)) return(lines)
  for (offset in seq.int(0L, length(data) - 1L, by = 16L)) {
    piece <- data[seq.int(offset + 1L, min(offset + 16L, length(data)))]
    bytes <- paste(sprintf("%02x", piece), collapse = " ")
    text <- paste(
        vapply(piece, function(byte) if (byte >= 32L && byte <= 126L) intToUtf8(byte) else ".", ""),
        collapse = ""
    )
    lines <- c(lines, sprintf("%04x  %-47s  |%s|", offset, bytes, text))
  }
  lines
}

malformed <- function(reason) {
  stop(structure(list(message = reason, call = NULL), class = c("malformed", "error", "condition")))
}
new_layer <- function() {
  new_object(fields = list(), next_layer = NULL, payload = integer(), remaining = integer())
}
byte_slice <- function(data, start, size) {
  if (size == 0) integer() else data[seq.int(start + 1L, start + size)]
}
read_integer <- function(data, position, count) {
  value <- 0
  for (byte in byte_slice(data, position, count)) value <- value * 256 + byte
  value
}
integer_bytes <- function(value, count) {
  as.integer(vapply(seq.int(count - 1L, 0L), function(power) (value %/% (256 ^ power)) %% 256, 0))
}
checksum_status <- function(data) {
  if (length(data) %% 2L) data <- c(data, 0L)
  total <- sum(data[seq.int(1L, length(data), by = 2L)] * 256 + data[seq.int(2L, length(data), by = 2L)])
  while (total > 65535) total <- (total %% 65536) + (total %/% 65536)
  if (total == 65535) "good" else "bad"
}
mac_notation <- function(value) paste(sprintf("%02x", integer_bytes(value, 6L)), collapse = ":")
ipv4_notation <- function(value) paste(integer_bytes(value, 4L), collapse = ".")
forward <- function(layer, name, payload) {
  layer$next_layer <- name
  layer$payload <- payload
}
dissect_ethernet <- function(frame) {
  if (length(frame) < 14L) malformed("eth: truncated")
  layer <- new_layer()
  type <- read_integer(frame, 12L, 2L)
  set_field(layer, "eth.dst", read_integer(frame, 0L, 6L))
  set_field(layer, "eth.src", read_integer(frame, 6L, 6L))
  set_field(layer, "eth.type", type)
  payload <- byte_slice(frame, 14L, length(frame) - 14L)
  if (type %in% c(2054, 2048)) {
    forward(layer, if (type == 2054) "arp" else "ip", payload)
  } else layer$remaining <- payload
  layer
}
dissect_arp <- function(message) {
  if (length(message) < 28L) malformed("arp: truncated")
  if (read_integer(message, 0L, 2L) != 1 || read_integer(
      message,
      2L,
      2L
  ) != 2048 || message[[5L]] != 6L || message[[6L]] != 4L) {
    malformed("arp: unsupported format")
  }
  layer <- new_layer()
  names <- c("arp.opcode", "arp.src.hw", "arp.src.ip", "arp.dst.hw", "arp.dst.ip")
  starts <- c(6L, 8L, 14L, 18L, 24L)
  sizes <- c(2L, 6L, 4L, 6L, 4L)
  for (i in seq_along(names)) set_field(layer, names[[i]], read_integer(message, starts[[i]], sizes[[i]]))
  layer
}
dissect_ipv4 <- function(datagram) {
  available <- length(datagram)
  if (available < 20L) malformed("ip: truncated header")
  version <- datagram[[1L]] %/% 16L
  if (version != 4L) malformed(paste("ip: bad version", version))
  header <- (datagram[[1L]] %% 16L) * 4L
  if (header < 20L) malformed(paste("ip: bad header length", header))
  if (available < header) malformed("ip: truncated header")
  total <- read_integer(datagram, 2L, 2L)
  if (total < header) malformed(paste("ip: bad total length", total))
  if (total > available) malformed(sprintf(
      "ip: truncated (total length %.0f, available %d)",
      total,
      available
  ))
  flags <- read_integer(datagram, 6L, 2L)
  more <- (flags %/% 8192) %% 2
  offset <- (flags %% 8192) * 8
  protocol <- datagram[[10L]]
  layer <- new_layer()
  values <- list(
    "ip.hdr_len" = header, "ip.tos" = datagram[[2L]], "ip.len" = total,
    "ip.id" = read_integer(datagram, 4L, 2L), "ip.flags.df" = (flags %/% 16384) %% 2,
    "ip.flags.mf" = more, "ip.frag_offset" = offset, "ip.ttl" = datagram[[9L]],
    "ip.proto" = protocol, "ip.checksum" = read_integer(datagram, 10L, 2L),
    "ip.checksum.status" = checksum_status(byte_slice(datagram, 0L, header)),
    "ip.src" = read_integer(datagram, 12L, 4L), "ip.dst" = read_integer(datagram, 16L, 4L)
  )
  for (name in names(values)) set_field(layer, name, values[[name]])
  payload <- byte_slice(datagram, header, total - header)
  if (more == 1 || offset != 0) {
    set_field(layer, "ip.fragment", TRUE)
    layer$remaining <- payload
  } else if (protocol %in% c(1L, 17L, 6L)) {
    next_layer <- if (protocol == 1L) "icmp" else if (protocol == 17L) "udp" else "tcp"
    forward(layer, next_layer, payload)
  } else layer$remaining <- payload
  layer
}

