    row <- c(
        ipv4_notation(endpoint$address),
        integer_text(c(
            endpoint_packets(endpoint),
            endpoint_bytes(endpoint),
            endpoint$tx_packets,
            endpoint$tx_bytes,
            endpoint$rx_packets,
            endpoint$rx_bytes
        ))
    )
    lines <- c(lines, paste(row, collapse = ","))
  }
